import{z as i,x as A,o as r,c as p,q as o,j as l,D as e,d as t,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Akerlof 柠檬市场原文","description":"","frontmatter":{"title":"Akerlof 柠檬市场原文","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/akerlof-1970.md","filePath":"econ/akerlof-1970.md","lastUpdated":1791413859000}'),B={name:"econ/akerlof-1970.md"};function d(c,a,f,m,h,D){const E=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="akerlof-柠檬市场原文" tabindex="-1">Akerlof 柠檬市场原文 <a class="header-anchor" href="#akerlof-柠檬市场原文" aria-label="Permalink to &quot;Akerlof 柠檬市场原文&quot;">​</a></h1><div class="epigraph"><p>质量不确定时，买方按平均质量出价，卖方只把次品投入市场，市场可以萎缩到零。</p><footer>—— Akerlof, The Market for &quot;Lemons&quot;: Quality Uncertainty and the Market Mechanism, Quarterly Journal of Economics 1970</footer></div><p><a href="/econ/debreu-theory-of-value">上一课</a>（Debreu 价值理论）。附录对照。主干<a href="/econ/akerlof-lemons">逆向选择与柠檬市场</a>已用这篇当机制默认。本篇对照 <strong>1970 原文的问题设定</strong>：不是贝叶斯博弈的精炼，而是「信息不对称如何让瓦尔拉斯市场失灵」。上一篇附录停在 Debreu 的完全信息竞争；这里从同一竞争语言里把质量改成私有信息。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原文从二手车起笔。卖者知道车是好车还是柠檬，买者只知道市场上的平均质量。若价格按平均质量定，好车的保留价值高于该价格，好车退出，平均质量再下降——逆向选择的螺旋。Akerlof 要说明的缺口是：这不是交易成本的小扰动，而是市场可以完全消失。Gresham 法则被拿来当类比：坏的驱逐好的，但这里驱逐发生在质量不可验证、而非法定劣币。</p><p>文章后半把同一结构搬到保险、少数族裔就业、信贷与发展中的资本市场——论证这是一种普遍的市场失灵，不是汽车业轶事。担保、品牌、执照被写成对抗逆向选择的制度，而不是道德说教。</p><p><span class="marginnote">题名中的 lemons 是美式口语的次品车。模型用连续质量与线性效用的简单供需，没有信号、没有筛选合同。那些是后两篇附录。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设质量 \\(q\\) 均匀分布，卖者保留效用为 \\(q\\)，买者对同一 \\(q\\) 的评价更高（例如 \\(\\frac{3}{2}q\\)）。买者按市场平均质量出价。均衡要满足：愿意出售的集合与买者信念一致。原文展示可以没有交易，或只留下最差的一层。关键假设是价格不能按个体质量条件化——因为买者看不见 \\(q\\)。</p><p><span class="marginnote">数字实例：设 \\(q\\) 在 \\([0,1]\\) 均匀分布。买者只知平均，出价 \\(p=1/2\\)；于是 \\(q\\gt 1/2\\) 的好车退出，剩下车的平均质量只有 \\(1/4\\)；买者改出 \\(1/4\\)，又有 \\(q\\in[1/4,1/2]\\) 的车退出……每一轮价格都被自己的后果腰斩，最后只剩 \\(q=0\\)，交易归零。</span></p>',10)),(r(),l(s,null,{default:e(()=>[n(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%BB%B7%E6%A0%BC%E6%8C%89%E5%B9%B3%E5%9D%87%E8%B4%A8%E9%87%8F%22%5D%20--%3E%20EXIT%5B%22%E5%A5%BD%E8%BD%A6%E9%80%80%E5%87%BA%22%5D%0A%20%20EXIT%20--%3E%20AVG%5B%22%E5%B9%B3%E5%9D%87%E8%B4%A8%E9%87%8F%E4%B8%8B%E9%99%8D%22%5D%0A%20%20AVG%20--%3E%20P%0A%20%20AVG%20--%3E%20ZERO%5B%22%E4%BA%A4%E6%98%93%E5%8F%AF%E4%BB%A5%E5%88%B0%E9%9B%B6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>没有博弈论术语。没有「类型、策略、完美贝叶斯」。主干课用后起的博弈语言重写了同一螺旋；附录对照的是原文用供需语言就写完了失灵。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是信念与供给集合的联立。价格既是支付，也是对留下的质量的推断；推断反过来决定谁留下。Debreu 的价格只传递稀缺，不传递对方私有信息，所以第一福利定理在这里不适用——不是因为外部性，是因为商品的真实属性未进入买者的消费集描述。担保与品牌把部分质量变成可合同的，等于把商品空间重新变回 Debreu 可写的那种。</p><p><span class="marginnote">常见误区：初学者容易把柠檬市场读成「买者太傻」或「卖者太坏」。其实双方都理性：卖者不肯亏本卖好车，买者不敢按好车出价——坏的不是人，是「价格无法按个体质量区分」这个信息结构本身。</span></p><h3 id="对照主干柠檬课-不插入均衡课中间" tabindex="-1">对照主干柠檬课，不插入均衡课中间 <a class="header-anchor" href="#对照主干柠檬课-不插入均衡课中间" aria-label="Permalink to &quot;对照主干柠檬课，不插入均衡课中间&quot;">​</a></h3><p>主干<a href="/econ/akerlof-lemons">逆向选择</a>已用螺旋当机制。本附录对照原文的问题设定：市场为何可以不存在，以及保险、信贷、少数群体就业被写成同一结构。没有信号、没有筛选菜单、没有精炼贝叶斯。那些是后两篇附录与主干后课。把 1970 插进<a href="/econ/core-equivalence">核等价</a>之后当作「第 5.5 课」，会打断一般均衡的福利链。</p><p><span class="marginnote"><em>QJE</em> 84(3), 1970, 488–500。题名里的 lemons 是次品车的口语。不要发明 arXiv。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>原文没有解决「为什么还会有新车市场、为什么有检测」。它点到制度，不建模信号成本——下一篇 <a href="/econ/spence-1973">Spence 1973</a> 才把可观察行动写成分离工具。也不要把 1970 的信贷例子读成已经包含 Stiglitz–Weiss 配给：那是另一篇。引用时用 <em>QJE</em> 1970，不要把后来教科书的均匀分布数字当成原文独有的定理编号。</p><p>这与 Diamond–Dybvig 挤兑不同：那里质量可以公开，坏均衡来自序贯服务。柠檬是质量随参与集内生恶化。</p><p>也不要与道德风险混淆：签约前的隐藏类型，不是签约后的隐藏行动。</p><p><span class="marginnote">术语翻译：逆向选择是「签约前隐藏类型」——保险公司不知道你已带病（投保的人本来就是高风险的那批）；道德风险是「签约后隐藏行动」——买了保险后你就不锁门了。柠檬属于前者：买者的问题是你是谁，不是你干了什么。</span></p>',12)),(r(),l(s,null,{default:e(()=>[n(E,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%B4%A8%E9%87%8F%20q%20%E4%B9%B0%E8%80%85%E7%9C%8B%E4%B8%8D%E8%A7%81%22%5D%20--%3E%20GUAR%5B%22%E6%8B%85%E4%BF%9D%3A%20%E5%9D%8F%E4%BA%86%E8%B5%94%2C%20%E5%8D%96%E8%80%85%E8%87%AA%E8%AF%81%22%5D%0A%20%20Q%20--%3E%20BRAND%5B%22%E5%93%81%E7%89%8C%3A%20%E9%87%8D%E5%A4%8D%E7%94%9F%E6%84%8F%E5%BD%93%E6%8A%B5%E6%8A%BC%22%5D%0A%20%20Q%20--%3E%20CERT%5B%22%E6%89%A7%E7%85%A7%3A%20%E7%AC%AC%E4%B8%89%E6%96%B9%E4%BA%8B%E5%89%8D%E7%AD%9B%E9%80%89%22%5D%0A%20%20GUAR%20--%3E%20OK%5B%22%E9%83%A8%E5%88%86%E8%B4%A8%E9%87%8F%E5%8F%98%E6%88%90%E5%8F%AF%E5%90%88%E5%90%8C%22%5D%0A%20%20BRAND%20--%3E%20OK%0A%20%20CERT%20--%3E%20OK%0A%20%20OK%20--%3E%20OPEN%5B%22%E5%B8%82%E5%9C%BA%E9%87%8D%E5%BC%80%3A%20%E8%9E%BA%E6%97%8B%E8%A2%AB%E5%88%87%E6%96%AD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p>原文没有计量表。二手车数据检验是后来文献。担保与品牌在原文是点到的制度，不是已经写成的信号博弈。</p><p>把 1970 插进一般均衡课序中间，会打断福利定理链。对照链接指向主干柠檬课即可。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Akerlof 1970：不可观察质量使平均定价驱逐好车，市场可关闭。</li><li>方法是供需加一致信念，不是信号博弈。</li><li>制度（担保、品牌）被写成对抗逆向选择，而不是附录外的伦理。</li><li>出处：Akerlof, <em>QJE</em> 1970。</li></ul>',4))])}const k=i(B,[["render",d]]);export{u as __pageData,k as default};
